from lib import *
S = SS('l23')
steps = [
    step("在分支上时,.git/HEAD 是一个文本文件,内容是 ref: refs/heads/main(符号引用);git symbolic-ref HEAD 输出 refs/heads/main;git rev-parse HEAD 解出的 e79e434670c8… 与 .git/refs/heads/main 文件里的 hash 完全相同。HEAD 本身不存提交,它存“当前分支是哪个”。", t=tl(S(1)), mark=lidx(S(1), 'ref: refs/heads/main'), done=lidx(S(1), 'refs/heads/main', 'e79e434670c8'), kv=KV([['.git/HEAD', 'ref: refs/heads/main'], ['分支文件', '.git/refs/heads/main 里是 40 位 hash'], ['rev-parse HEAD', '沿着符号引用解出提交']], ['.git/HEAD'])),
    step("git checkout 9867bdd…(提交 2 的完整 hash)进入 detached HEAD:.git/HEAD 的内容直接变成 hash(9867bddbd4ae…);git symbolic-ref HEAD 报错 fatal: ref HEAD is not a symbolic ref;git status 显示 HEAD detached at 9867bdd;git branch 列出 * (HEAD detached at 9867bdd)。所谓 detached,就是 HEAD 不再指向某个分支,而是直接指向一个提交。", t=tl(S(2)), mark=lidx(S(2), 'is not a symbolic ref', 'HEAD detached at'), done=lidx(S(2), '9867bddbd4ae', 'git branch'), kv=KV([['detached HEAD', '.git/HEAD 里直接是 hash'], ['symbolic-ref', '报错:不是符号引用'], ['git branch', '显示 (HEAD detached at …)']], ['detached HEAD'])),
    step("在 detached HEAD 上提交 b.txt:新提交 690e7c4 只有 HEAD 指着它,git log --all --graph 里它和 main 上的提交 3(e79e434)分叉自提交 2。切回 main 时 git 警告 you are leaving 1 commit behind, not connected to any of your branches,并给出建议命令 git branch <new-branch-name> 690e7c4。", t=tl(S(3)), mark=lidx(S(3), 'leaving 1 commit behind', 'git branch <new-branch-name>', '690e7c4 detached 上的提交'), done=lidx(S(3), 'git log --oneline --all --graph', 'HEAD detached from 9867bdd', 'Switched to branch'), kv=KV([['detached 上的提交', '只有 HEAD 指着'], ['切走时', '警告:提交不属于任何分支'], ['建议', 'git branch <名字> <hash>']], ['detached 上的提交'])),
    step("切回 main 之后,git branch --contains <hash> 没有任何输出——没有分支包含它。但 reflog 记着一切:HEAD@{1} 是 commit: detached 上的提交,HEAD@{0} 是 checkout: moving from 690e7c4… to main。用 reflog 里的 hash 执行 git switch -c rescued <hash>,git log rescued 看到 detached 上的提交、提交 2、提交 1,找回来了。", t=tl(S(4)), mark=lidx(S(4), 'git switch -c rescued', 'Switched to a new branch', '690e7c4 detached 上的提交'), done=lidx(S(4), '9867bdd 提交 2', '88a540f 提交 1'), kv=KV([['没有分支包含它', 'git branch --contains 无输出'], ['reflog', '记着 HEAD 的每一次移动'], ['找回', 'git switch -c <名字> <hash>']], ['reflog'])),
    step("HEAD 以外的特殊引用都是 .git 里的文件,只在对应操作期间出现:平时一个都没有;git reset --hard HEAD~1 之后出现 ORIG_HEAD(内容是 reset 前的 e79e434670c8…,git reset --hard ORIG_HEAD 可以撤销);merge 冲突时出现 MERGE_HEAD(6aea679fd5ec…,要合并进来的提交),merge --abort 之后消失;cherry-pick 冲突时出现 CHERRY_PICK_HEAD;git fetch 之后出现 FETCH_HEAD,每行是 hash、not-for-merge 标记、来源分支(前两行 main、rescued)。", t=tl(S(5)), mark=lidx(S(5), 'MERGE_HEAD', 'CHERRY_PICK_HEAD', 'ORIG_HEAD', 'FETCH_HEAD'), done=lidx(S(5), '现在一个都没有', 'abort 之后 MERGE_HEAD 没了', 'not-for-merge'), kv=KV([['ORIG_HEAD', 'reset / merge / rebase 之前 HEAD 的位置'], ['MERGE_HEAD', '正在合并的提交,冲突时存在'], ['CHERRY_PICK_HEAD', 'cherry-pick 冲突时存在'], ['FETCH_HEAD', '最近一次 fetch 取回的引用']], ['ORIG_HEAD'])),
    step("新仓库里 .git/HEAD 是 ref: refs/heads/main,但 refs/heads/main 文件还不存在:git status 显示 No commits yet,git rev-parse HEAD 报 unknown revision,git log 报 your current branch 'main' does not have any commits yet——这就是“未出生的分支”(unborn)。用 git symbolic-ref HEAD refs/heads/其它名字 可以直接改 HEAD 指向的分支名,git checkout --orphan fresh 也是这个效果:HEAD 指向 refs/heads/fresh,工作区文件(a.txt)保留,但没有任何提交。", t=tl(S(6)), mark=lidx(S(6), 'No commits yet', 'does not have any commits yet', 'unknown revision'), done=lidx(S(6), 'ref: refs/heads/其它名字', 'ref: refs/heads/fresh', 'a.txt'), kv=KV([['unborn', 'HEAD 指向还不存在的分支'], ['symbolic-ref', '可以直接改 HEAD 指向'], ['--orphan', '新分支没有 parent,工作区保留']], ['unborn'])),
]
A = mkarti('l23', 23, 'Git,HEAD,detached HEAD,symbolic-ref,reflog,真实验证,动画演示',
    '在真实仓库里观察 HEAD:在分支上 .git/HEAD 是 ref: refs/heads/main,detached 时直接是 hash,symbolic-ref 报错;在 detached HEAD 上提交后切走,git 警告会丢下一个提交,reflog 里能找回;ORIG_HEAD、MERGE_HEAD、CHERRY_PICK_HEAD、FETCH_HEAD 是只在对应操作中出现的文件;新仓库和 --orphan 的未出生分支。',
    'HEAD 到底是什么?detached HEAD 又是怎么回事,在上面提交会怎样?这篇直接看 .git/HEAD 文件在各种状态下的内容,再看 reflog 如何帮你找回 detached 上的提交,最后认识 ORIG_HEAD、MERGE_HEAD 等几个特殊文件。',
    [('2 种形式', '.git/HEAD 要么是 ref: refs/heads/<分支>,要么直接是 40 位 hash(detached)'), ('1 个提交', '从 detached HEAD 切回 main 时 git 警告“丢下 1 个不属于任何分支的提交”,reflog 能把它找回来'), ('4 个文件', 'ORIG_HEAD、MERGE_HEAD、CHERRY_PICK_HEAD、FETCH_HEAD,只在对应操作期间或之后出现')],
    [('HEAD 是什么', '<p><code>.git/HEAD</code> 在分支上是 <code>ref: refs/heads/main</code> 这样的符号引用,真正的提交 hash 存在 <code>.git/refs/heads/main</code> 里;HEAD 本身并不存提交。</p>'),
     ('detached', '<p><code>git checkout &lt;commit&gt;</code> 之后 HEAD 里直接是 hash,<code>git symbolic-ref HEAD</code> 报错“不是符号引用”,<code>git status</code> 提示 detached。这时 HEAD 不再跟着任何分支。</p>'),
     ('在 detached 上提交', '<p>新提交只有 HEAD 指着它,不属于任何分支。切走时 git 会警告,并建议 <code>git branch &lt;名字&gt; &lt;hash&gt;</code>。如果错过警告,<code>git branch --contains</code> 查不到它。</p>'),
     ('用 reflog 找回', '<p>reflog 记录了 HEAD 的每一次移动,其中包括这个提交的 hash;用它起一个分支就找回来了。这是 reflog 最典型的用途(见后面 reflog 一篇)。</p>'),
     ('特殊引用', '<p><code>ORIG_HEAD</code>(危险操作之前 HEAD 的位置)、<code>MERGE_HEAD</code>(正在合并的提交)、<code>CHERRY_PICK_HEAD</code>(cherry-pick 冲突)、<code>FETCH_HEAD</code>(最近一次 fetch)都是 <code>.git</code> 里的普通文件,命令结束或中止后有的消失,有的保留。</p>'),
     ('未出生的分支', '<p>HEAD 可以指向一个还没有任何提交的分支名:新仓库、<code>git symbolic-ref HEAD refs/heads/xxx</code>、<code>git checkout --orphan</code> 都是这样,<code>git log</code> 和 <code>git rev-parse HEAD</code> 会报“还没有提交”。</p>')],
    steps,
    [ENV_I_GIT + '。所有输出都来自真实命令;FETCH_HEAD 实验用本机另一个目录当远程;hash 因作者与时间固定而可复现(detached 上的提交 690e7c4 等)',
     '没有验证:git worktree 下每个工作树各自的 HEAD(后面有 worktree 一篇);rebase 期间的 REBASE_HEAD 与 .git/rebase-merge 目录(见 rebase 一篇);bisect 期间的 BISECT_HEAD;reflog 的过期(见 reflog 一篇);git switch --detach 与 git checkout --detach 的差别'],
    'HEAD 与 detached HEAD')
